SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
START TRANSACTION;
-- Temporarily reopen final lessons for activity audio metadata updates.
DROP TEMPORARY TABLE IF EXISTS _audio_mapping_lesson_status;
CREATE TEMPORARY TABLE _audio_mapping_lesson_status AS
SELECT DISTINCT le.id AS lesson_id, le.status AS original_status
FROM lessons le JOIN activities a ON a.lesson_id=le.id
WHERE a.activity_key IN ('act-de-age-listen','act-de-phone-listen','act-de-price-listen','act-de-time-listen');
UPDATE lessons le JOIN _audio_mapping_lesson_status s ON s.lesson_id=le.id
SET le.status='qa'
WHERE s.original_status='final';
